class CircularBuffer:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self._buf = [None] * capacity
        self._cap = capacity
        self._head = 0
        self._size = 0

    def __len__(self):
        return self._size

    @property
    def is_empty(self):
        return self._size == 0

    @property
    def is_full(self):
        return self._size == self._cap

    def enqueue(self, item):
        if self.is_full:
            raise OverflowError("Buffer is full")
        self._buf[self._head] = item
        self._head = (self._head + 1) % self._cap
        self._size += 1

    def dequeue(self):
        if self.is_empty:
            raise IndexError("Buffer is empty")
        tail = (self._head - self._size) % self._cap
        item = self._buf[tail]
        self._buf[tail] = None
        self._size -= 1
        return item

    def peek(self):
        if self.is_empty:
            raise IndexError("Buffer is empty")
        tail = (self._head - self._size) % self._cap
        return self._buf[tail]


if __name__ == "__main__":
    buf = CircularBuffer(3)
    buf.enqueue("a")
    buf.enqueue("b")
    buf.enqueue("c")
    assert buf.is_full
    assert buf.dequeue() == "a"
    assert buf.dequeue() == "b"
    buf.enqueue("d")
    assert buf.dequeue() == "c"
    assert buf.dequeue() == "d"
    assert buf.is_empty
    print("All tests passed.")
